def norm(t):
    t = re.sub(r'[*#\s《》|—\-，。；;：:、（）()]', '', t or '')
    for ch in '\u201c\u201d\u2018\u2019' + chr(34) + '\u300c\u300d':
        t = t.replace(ch, '')
    return t

def md5(s):
    return hashlib.md5(s.encode('utf-8')).hexdigest()

def clean_title(t):
    t = re.sub(r'[\n\r' + chr(34) + chr(39) + '《》【】#*“”‘’]', '', t or '').strip()
    t = re.sub(r'\s+', ' ', t)
    return t[:30]

def split_sentences(text):
    sents, buf = [], ''
    open_q = False
    lines = text.split('\n')
    for line in lines:
        ls = line.strip()
        if ls.startswith('|'):
            if buf.strip():
                sents.append(buf.strip()); buf = ''
            if ls:
                sents.append(ls)
            continue
        for ch in line:
            buf += ch
            if ch in '\u201c\u2018\u300c"':
                open_q = True
            elif ch in '\u201d\u2019\u300d"':
                open_q = False
            if ch in '。！？；' and not open_q:
                s = buf.strip()
                if s:
                    sents.append(s)
                buf = ''
    if buf.strip():
        sents.append(buf.strip())
    return sents

def split_blocks(sentences, max_sents=150):
    if len(sentences) <= max_sents:
        return [sentences]
    blocks, cur = [], []
    for s in sentences:
        is_heading = bool(re.match(r'^\s*(第[一二三四五六七八九十百零]+[章节部分篇])', s))
        if is_heading and cur and len(cur) >= max_sents // 2:
            blocks.append(cur); cur = []
        cur.append(s)
        if len(cur) >= max_sents:
            blocks.append(cur); cur = []
    if cur:
        blocks.append(cur)
    return blocks


